import math
from collections import Counter, defaultdict
import sys
import heapq

def overlap(res):
	res.sort()
	res2 = [res[0]]
	for i in res:
		if i[0] <= res2[-1][1] and i[1] <= res2[-1][1]:
			continue
		elif i[0] <= res2[-1][1] and i[1] >= res2[-1][1]:
			res2[-1][1] = i[1]
		else:
			res2.append(i)
	min_res = 0
	for i in res2:
		min_res += i[1] - i[0]
	return min_res

def solve():
	arr.sort()
	max_res = arr[-1]
	heap = []
	for i in range(n - 2, -1, -1):
		heapq.heappush(heap, -arr[i])
	for i in range(n - 1):
		val = -heapq.heappop(heap)
		if val > u:
			max_res += u
			heapq.heappush(heap, -(val - u))
		else:
			max_res += val
	arr.sort(reverse=True)
	pos = 0
	res = []
	for i in arr:
		pos += l
		res.append([pos, pos + i])
	min_res = overlap(res)
	return (min_res, max_res)
for _ in range(int(input())):
	(n, l, u) = map(int, input().split())
	arr = list(map(int, input().split()))
	print(*solve())
